//! Fixture-driven tests for the reports crypto, key derivation, alignment and JSON round-trips,
//! generated by the real Python (`app/tools/oracle/reports_vectors.py`).

use apple_core::reports::crypto;
use apple_core::reports::keys::{parse_iso, AccessoryKeys, KeyPair, KeyPairType};
use apple_core::reports::payload::{EncryptedReport, APPLE_EPOCH_OFFSET};
use base64::Engine as _;
use serde_json::Value;
use time::OffsetDateTime;

fn fixture(name: &str) -> Value {
    let path = format!(
        "{}/../../app/android/app/src/test/resources/fixtures/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap()
}

fn b64(s: &str) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD.decode(s).unwrap()
}

fn hexvec(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn type_name(t: KeyPairType) -> &'static str {
    match t {
        KeyPairType::Primary => "PRIMARY",
        KeyPairType::Secondary => "SECONDARY",
        KeyPairType::Unknown => "UNKNOWN",
    }
}

fn accessory_from(value: &Value) -> AccessoryKeys {
    AccessoryKeys::from_json(value).expect("accessory")
}

#[test]
fn kdf_and_derive() {
    let d = fixture("reports/keys.json");
    for case in d["kdf"].as_array().unwrap() {
        let out = crypto::x963_kdf(
            &hexvec(case["value"].as_str().unwrap()),
            &hexvec(case["si"].as_str().unwrap()),
            case["length"].as_u64().unwrap() as usize,
        );
        assert_eq!(hex(&out), case["out"].as_str().unwrap());
    }
    for case in d["derive"].as_array().unwrap() {
        let out = crypto::derive_ps_key(
            &hexvec(case["master"].as_str().unwrap()),
            &hexvec(case["sk"].as_str().unwrap()),
        );
        assert_eq!(hex(&out), case["out"].as_str().unwrap());
    }
}

#[test]
fn keypairs_match() {
    let d = fixture("reports/keys.json");
    for case in d["keypairs"].as_array().unwrap() {
        let key = KeyPair::new(&hexvec(case["priv"].as_str().unwrap()), KeyPairType::Unknown, None).unwrap();
        assert_eq!(key.adv_key_b64(), case["adv"].as_str().unwrap());
        assert_eq!(key.hashed_adv_key_b64(), case["hashed"].as_str().unwrap());
        assert_eq!(hex(&key.private_key_bytes()), case["priv"].as_str().unwrap());
    }
}

#[test]
fn keys_at_and_between() {
    let d = fixture("reports/keys.json");
    for acc in d["accessories"].as_array().unwrap() {
        let accessory = AccessoryKeys::new(
            hexvec(acc["master"].as_str().unwrap()),
            hexvec(acc["skn"].as_str().unwrap()),
            hexvec(acc["sks"].as_str().unwrap()),
            OffsetDateTime::from_unix_timestamp(0).unwrap(),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        )
        .unwrap();
        for (index_s, expected) in acc["keys_at"].as_object().unwrap() {
            let index: i32 = index_s.parse().unwrap();
            let got: std::collections::HashSet<(String, String)> = accessory
                .keys_at(index)
                .unwrap()
                .iter()
                .map(|k| (k.hashed_adv_key_b64(), type_name(k.key_type()).to_string()))
                .collect();
            let want: std::collections::HashSet<(String, String)> = expected
                .as_array()
                .unwrap()
                .iter()
                .map(|e| {
                    (
                        e["hashed"].as_str().unwrap().to_string(),
                        e["type"].as_str().unwrap().to_string(),
                    )
                })
                .collect();
            assert_eq!(got, want, "keys_at {index}");
        }
        // A couple of entries of the primary/secondary caches.
        for (index_s, expected) in acc["primary"].as_object().unwrap() {
            let key = accessory.primary_key_at(index_s.parse().unwrap()).unwrap();
            assert_eq!(hex(&key.private_key_bytes()), expected["priv"].as_str().unwrap(), "primary {index_s}");
            assert_eq!(key.adv_key_b64(), expected["adv"].as_str().unwrap(), "primary adv {index_s}");
            assert_eq!(key.hashed_adv_key_b64(), expected["hashed"].as_str().unwrap(), "primary hashed {index_s}");
        }
    }

    let accessory = accessory_from(&d["between_accessory"]);
    for case in d["between"].as_array().unwrap() {
        let got: std::collections::HashSet<(i32, String, String)> = if case["start"].is_number() {
            let start = case["start"].as_i64().unwrap() as i32;
            let end = case["end"].as_i64().unwrap() as i32;
            accessory
                .keys_between(start, end)
                .unwrap()
                .iter()
                .map(|(i, k)| (*i, k.hashed_adv_key_b64(), type_name(k.key_type()).to_string()))
                .collect()
        } else {
            let start = parse_iso(case["start"].as_str().unwrap()).unwrap();
            let end = parse_iso(case["end"].as_str().unwrap()).unwrap();
            accessory
                .keys_between_times(start, end)
                .unwrap()
                .iter()
                .map(|(i, k)| (*i, k.hashed_adv_key_b64(), type_name(k.key_type()).to_string()))
                .collect()
        };
        let want: std::collections::HashSet<(i32, String, String)> = case["items"]
            .as_array()
            .unwrap()
            .iter()
            .map(|e| {
                (
                    e["index"].as_i64().unwrap() as i32,
                    e["hashed"].as_str().unwrap().to_string(),
                    e["type"].as_str().unwrap().to_string(),
                )
            })
            .collect();
        assert_eq!(got, want, "between {}..{}", case["name"], case["name"]);
    }
}

#[test]
fn alignment_queries_and_updates() {
    let d = fixture("reports/alignment.json");
    let accessory = accessory_from(&d["accessory"]);

    for q in d["queries"].as_array().unwrap() {
        let at = parse_iso(q["at"].as_str().unwrap()).unwrap();
        assert_eq!(accessory.min_index(at), q["min"].as_i64().unwrap() as i32, "min at {}", q["at"]);
        assert_eq!(accessory.max_index(at), q["max"].as_i64().unwrap() as i32, "max at {}", q["at"]);
    }

    let eval_at = parse_iso(d["accessory"]["alignment_date"].as_str().unwrap()).unwrap()
        + time::Duration::days(1);
    for u in d["updates"].as_array().unwrap() {
        let at = parse_iso(u["at"].as_str().unwrap()).unwrap();
        let index = u["index"].as_i64().unwrap() as i32;
        accessory.update_alignment(at, index);
        assert_eq!(accessory.alignment_index(), u["alignment_index"].as_i64().unwrap() as i32, "update index");
        assert_eq!(
            apple_core::reports::keys::isoformat(accessory.alignment_date()),
            u["alignment_date"].as_str().unwrap(),
            "update date"
        );
        assert_eq!(accessory.min_index(eval_at), u["min"].as_i64().unwrap() as i32, "update min");
        assert_eq!(accessory.max_index(eval_at), u["max"].as_i64().unwrap() as i32, "update max");
    }
}

#[test]
fn accessory_json_round_trips() {
    let d = fixture("reports/accessory_json.json");
    for case in d["cases"].as_array().unwrap() {
        let accessory = AccessoryKeys::from_json(&case["input"]).unwrap();
        assert_eq!(accessory.to_json(), case["python_roundtrip"], "roundtrip {}", case["name"]);
    }
    for case in d["bad"].as_array().unwrap() {
        assert!(
            AccessoryKeys::from_json(&case["input"]).is_err(),
            "expected an error for {}",
            case["name"]
        );
    }
    for case in d["serials"].as_array().unwrap() {
        let input: Option<Vec<String>> = case["input"]
            .as_array()
            .map(|a| a.iter().map(|v| v.as_str().unwrap().to_string()).collect());
        let want = case["out"].as_str().map(str::to_string);
        assert_eq!(
            apple_core::reports::keys::serial_from_stable_identifier(input.as_deref()),
            want,
            "serial {}",
            case
        );
    }
}

#[test]
fn decrypt_vectors() {
    let d = fixture("reports/decrypt.json");
    let key = KeyPair::new(&hexvec(d["key"].as_str().unwrap()), KeyPairType::Unknown, None).unwrap();

    for case in d["valid"].as_array().unwrap() {
        let report = EncryptedReport::new(
            b64(case["payload"].as_str().unwrap()),
            b64(case["hashed"].as_str().unwrap()),
        );
        let out = report.decrypt(&key).expect("valid report");
        let py = &case["py"];
        assert_eq!(out.timestamp, py["ts"].as_i64().unwrap());
        assert_eq!(out.latitude(), py["lat"].as_f64().unwrap());
        assert_eq!(out.longitude(), py["lon"].as_f64().unwrap());
        assert_eq!(out.horizontal_accuracy as i64, py["acc"].as_i64().unwrap());
        assert_eq!(out.confidence as i64, py["conf"].as_i64().unwrap());
        assert_eq!(out.status as i64, py["status"].as_i64().unwrap());
    }

    for case in d["malformed"].as_array().unwrap() {
        let report = EncryptedReport::new(
            b64(case["payload"].as_str().unwrap()),
            b64(case["hashed"].as_str().unwrap()),
        );
        let out = report.decrypt(&key);
        let expected_ok = case["py"]["ok"].as_bool().unwrap();
        assert_eq!(out.is_ok(), expected_ok, "malformed {}", case["name"]);
        if expected_ok {
            let py = &case["py"];
            let out = out.unwrap();
            assert_eq!(out.timestamp, py["ts"].as_i64().unwrap(), "{}", case["name"]);
            assert_eq!(out.latitude(), py["lat"].as_f64().unwrap(), "{}", case["name"]);
        }
    }
}

#[test]
fn apple_epoch_is_constant() {
    assert_eq!(APPLE_EPOCH_OFFSET, 978_307_200);
}

// ------------------------------------------------------------------------------------ fetch

mod fetch {
    use std::collections::BTreeMap;
    use std::sync::Arc;
    use std::time::Duration;

    use apple_core::error::Result;
    use apple_core::http::Http;
    use apple_core::login::BoxFuture;
    use apple_core::reports::client::{AccountContext, ReportClient};
    use apple_core::reports::keys::{AccessoryKeys, KeyPair};
    use base64::Engine as _;
    use serde_json::{json, Value};
    use sha2::{Digest, Sha256};
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    use tokio::net::TcpListener;
    use tokio::sync::Mutex;

    struct FakeAccount {
        http: Http,
    }

    impl AccountContext for FakeAccount {
        fn service_token<'a>(&'a self, name: &'a str) -> BoxFuture<'a, Option<String>> {
            Box::pin(async move { (name == "searchPartyToken").then(|| "SP-TOKEN".to_string()) })
        }
        fn dsid<'a>(&'a self) -> BoxFuture<'a, Result<String>> {
            Box::pin(async move { Ok("1234567890".to_string()) })
        }
        fn anisette_headers<'a>(&'a self) -> BoxFuture<'a, Result<BTreeMap<String, String>>> {
            Box::pin(async move { Ok(BTreeMap::new()) })
        }
        fn refresh_session<'a>(&'a self) -> BoxFuture<'a, Result<()>> {
            Box::pin(async move { Ok(()) })
        }
        fn http(&self) -> &Http {
            &self.http
        }
    }

    struct Server {
        calls: Arc<Mutex<Vec<Value>>>,
    }

    async fn start(replies: Vec<Vec<Value>>) -> (String, Server) {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let replies = Arc::new(Mutex::new(replies));
        let calls = Arc::new(Mutex::new(Vec::new()));
        let (r, c) = (replies.clone(), calls.clone());
        tokio::spawn(async move {
            loop {
                let Ok((mut socket, _)) = listener.accept().await else { break };
                let (r, c) = (r.clone(), c.clone());
                tokio::spawn(async move {
                    let Some(body) = read_body(&mut socket).await else { return };
                    let req: Value = serde_json::from_slice(&body).unwrap_or(Value::Null);
                    let fetch = req.get("fetch").cloned().unwrap_or(Value::Null);
                    c.lock().await.push(fetch);
                    let index = c.lock().await.len() - 1;
                    let call = {
                        let guard = r.lock().await;
                        guard.get(index).cloned().unwrap_or_default()
                    };
                    let payload: Vec<Value> = call
                        .iter()
                        .map(|item| {
                            json!({
                                "id": item["hashed"],
                                "locationInfo": [item["payload"]],
                            })
                        })
                        .collect();
                    let response = json!({
                        "acsnLocations": {"statusCode": "200", "locationPayload": payload}
                    })
                    .to_string();
                    let out = format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                        response.len(),
                        response
                    );
                    let _ = socket.write_all(out.as_bytes()).await;
                    let _ = socket.flush().await;
                });
            }
        });
        (format!("http://{addr}"), Server { calls })
    }

    async fn read_body(socket: &mut tokio::net::TcpStream) -> Option<Vec<u8>> {
        let mut buf = Vec::new();
        let mut tmp = [0u8; 4096];
        loop {
            let n = socket.read(&mut tmp).await.ok()?;
            if n == 0 {
                return None;
            }
            buf.extend_from_slice(&tmp[..n]);
            if let Some(pos) = buf.windows(4).position(|w| w == b"\r\n\r\n") {
                let head = String::from_utf8_lossy(&buf[..pos]).to_string();
                let content_length = head
                    .lines()
                    .filter_map(|l| l.split_once(':'))
                    .find(|(k, _)| k.eq_ignore_ascii_case("content-length"))
                    .and_then(|(_, v)| v.trim().parse::<usize>().ok())
                    .unwrap_or(0);
                let mut body = buf[pos + 4..].to_vec();
                while body.len() < content_length {
                    let n = socket.read(&mut tmp).await.ok()?;
                    if n == 0 {
                        break;
                    }
                    body.extend_from_slice(&tmp[..n]);
                }
                body.truncate(content_length);
                return Some(body);
            }
        }
    }

    fn fixture(name: &str) -> Value {
        let path = format!(
            "{}/../../app/android/app/src/test/resources/fixtures/{name}",
            env!("CARGO_MANIFEST_DIR")
        );
        serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap()
    }

    fn digest(ids: &[String]) -> Value {
        let mut sorted: Vec<String> = ids.to_vec();
        sorted.sort();
        let mut h = Sha256::new();
        h.update(sorted.join("\n").as_bytes());
        let ids_value = if sorted.len() <= 20 { json!(sorted) } else { Value::Null };
        json!({"count": sorted.len(), "sha256": format!("{:x}", h.finalize()), "ids": ids_value})
    }

    fn reports_json(result: &apple_core::reports::client::ReportFetchResult) -> Vec<Value> {
        result
            .reports
            .iter()
            .map(|r| {
                json!({
                    "ts": r.observed_at.unix_timestamp(),
                    "lat": r.latitude,
                    "lon": r.longitude,
                    "acc": r.horizontal_accuracy_meters.unwrap() as i64,
                    "status": r.metadata.get("status").and_then(|s| s.parse::<i64>().ok()).unwrap_or(0),
                    "conf": r.metadata.get("confidence").and_then(|s| s.parse::<i64>().ok()).unwrap_or(0),
                })
            })
            .collect()
    }

    fn check_reports(got: Vec<Value>, expected: &Value, name: &str, now_unix: i64) {
        let mut got = got;
        got.sort_by_key(|r| r["ts"].as_i64().unwrap());
        // The Rust follows the Kotlin's deliberate difference from the Python: reports at (0, 0)
        // or more than 5 minutes in the future are dropped by the domain rules.
        let mut want: Vec<Value> = expected
            .as_array()
            .unwrap()
            .iter()
            .filter(|e| {
                let lat = e["lat"].as_f64().unwrap();
                let lon = e["lon"].as_f64().unwrap();
                !(lat == 0.0 && lon == 0.0) && e["ts"].as_i64().unwrap() < now_unix + 300
            })
            .map(|e| {
                json!({
                    "ts": e["ts"], "lat": e["lat"], "lon": e["lon"],
                    "acc": e["acc"], "status": e["status"], "conf": e["conf"],
                })
            })
            .collect();
        want.sort_by_key(|r| r["ts"].as_i64().unwrap());
        assert_eq!(got, want, "{name}: reports");
    }

    fn check_calls(fetch_calls: &[Value], expected: &Value, name: &str) {
        let expected_calls = expected.as_array().unwrap();
        assert_eq!(fetch_calls.len(), expected_calls.len(), "{name}: call count");
        for (i, (got, want)) in fetch_calls.iter().zip(expected_calls).enumerate() {
            let got_entries = got.as_array().unwrap();
            let want_entries = want.as_array().unwrap();
            assert_eq!(got_entries.len(), want_entries.len(), "{name}: call {i} entries");
            for (j, (g, w)) in got_entries.iter().zip(want_entries).enumerate() {
                let primary_ok = if w["primary"].is_object() {
                    digest(
                        &g["primaryIds"]
                            .as_array()
                            .unwrap()
                            .iter()
                            .map(|v| v.as_str().unwrap().to_string())
                            .collect::<Vec<_>>(),
                    ) == w["primary"]
                } else {
                    g["primaryIds"] == w["primary"]
                };
                let secondary_ok = if w["secondary"].is_object() {
                    digest(
                        &g["secondaryIds"]
                            .as_array()
                            .unwrap()
                            .iter()
                            .map(|v| v.as_str().unwrap().to_string())
                            .collect::<Vec<_>>(),
                    ) == w["secondary"]
                } else {
                    g["secondaryIds"] == w["secondary"]
                };
                assert!(primary_ok, "{name}: call {i} entry {j} primary");
                assert!(secondary_ok, "{name}: call {i} entry {j} secondary");
            }
        }
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn rolling_fetch_matches_the_python() {
        let d = fixture("reports/fetch.json");
        for scenario in d["rolling"].as_array().unwrap() {
            let name = scenario["name"].as_str().unwrap();
            let replies: Vec<Vec<Value>> = scenario["replies"]
                .as_array()
                .unwrap()
                .iter()
                .map(|call| call.as_array().unwrap().to_vec())
                .collect();
            let (origin, server) = start(replies).await;
            let http = Http::new(Duration::from_secs(10)).unwrap();
            let account = FakeAccount { http };
            let accessory = AccessoryKeys::from_json(&scenario["accessory"]).unwrap();
            let now = apple_core::reports::keys::parse_iso(scenario["now"].as_str().unwrap()).unwrap();
            let only_latest = scenario["only_latest"].as_bool().unwrap();
            let client = ReportClient::new(&account)
                .with_endpoint(format!("{origin}/findmyservice/v2/fetch"))
                .with_clock(move || now);

            let result = client.fetch_location_history(&accessory, only_latest).await.unwrap();
            check_reports(reports_json(&result), &scenario["reports"], name, now.unix_timestamp());
            assert_eq!(
                accessory.alignment_date().unix_timestamp(),
                scenario["alignment_epoch"].as_i64().unwrap(),
                "{name}: alignment epoch"
            );
            assert_eq!(
                accessory.alignment_index(),
                scenario["alignment_index"].as_i64().unwrap() as i32,
                "{name}: alignment index"
            );
            let calls = server.calls.lock().await.clone();
            check_calls(&calls, &scenario["calls"], name);
        }
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn static_fetch_matches_the_python() {
        let d = fixture("reports/fetch.json");
        let scenario = &d["static"];
        let replies: Vec<Vec<Value>> = scenario["replies"]
            .as_array()
            .unwrap()
            .iter()
            .map(|call| call.as_array().unwrap().to_vec())
            .collect();
        let (origin, server) = start(replies).await;
        let http = Http::new(Duration::from_secs(10)).unwrap();
        let account = FakeAccount { http };
        let keys: Vec<KeyPair> = scenario["keys"]
            .as_array()
            .unwrap()
            .iter()
            .map(|k| KeyPair::from_b64(k.as_str().unwrap()).unwrap())
            .collect();
        let now = apple_core::reports::keys::parse_iso(scenario["now"].as_str().unwrap()).unwrap();
        let client = ReportClient::new(&account)
            .with_endpoint(format!("{origin}/findmyservice/v2/fetch"))
            .with_clock(move || now);

        let results = client.fetch_key_history(&keys).await.unwrap();
        for (key, result) in &results {
            let id = base64::engine::general_purpose::STANDARD.encode(key.private_key_bytes());
            check_reports(reports_json(result), &scenario["reports"][id.as_str()], &id, now.unix_timestamp());
        }
        let calls = server.calls.lock().await.clone();
        check_calls(&calls, &scenario["calls"], "static");
    }
}
